import sys


def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    raw_a = [int(x) for x in data[1 : n + 1]]

    # Remove consecutive duplicate heights
    a = []
    for x in raw_a:
        if not a or a[-1] != x:
            a.append(x)

    # Add sentinels with height 0 at both ends
    a = [0] + a + [0]
    m = len(a)

    events = {}
    for i in range(1, m - 1):
        if a[i] > a[i - 1] and a[i] > a[i + 1]:
            # Peak: a new component appears when going below this height
            events[a[i]] = events.get(a[i], 0) + 1
        elif a[i] < a[i - 1] and a[i] < a[i + 1]:
            # Valley: two components merge when going below this height
            events[a[i]] = events.get(a[i], 0) - 1

    # Process events in descending order of height
    sorted_heights = sorted(events.keys(), reverse=True)

    current_components = 0
    max_components = 0

    for h in sorted_heights:
        current_components += events[h]
        if current_components > max_components:
            max_components = current_components

    # Total pieces = bottom piece (1) + components above the cut
    print(1 + max_components)


if __name__ == "__main__":
    solve()
